def transform(grid):
    g = np.array(grid)
    bg = background(g)
    out = g.copy()
    H, W = g.shape
    for y in range(H):
        changed = False
        for x in range(1, W - 1):
            if g[y, x] == bg and g[y, x - 1] == 1 and g[y, x + 1] == 1:
                out[y, x] = 2
                changed = True
        if changed:
            emit(out, f"Row {y}: fill each gap between two horizontally adjacent-by-one 1s with 2.")
    emit(out, "All bridges between paired 1s are filled; final grid.")
    return out
